; sprite.asm -- chapter 10: a shape put on a background four ways
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "sprite.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
PANELS  EQU $C200               ; six panels of 32 x 32 pixels, 128 bytes each
blk_src EQU VARS + $10          ; showblk's working bytes, in the RAM
blk_rc  EQU VARS + $12
blk_k   EQU VARS + $14
blk_w   EQU VARS + $15
blk_h   EQU VARS + $16
; The data is three bytes for each byte of a panel: the background, the
; shape, and the mask, which has a 0 wherever the shape covers. Last, AND
; counts the bytes where the shape and the background touch.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, PANELS + 0
        call putback
        ld hl, PANELS + 0
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 128
        ld b, 2
        ld c, 2
        call showblk            ; the panel, as 16 characters
        ld b, 7
        ld c, 2
        ld hl, t0
        call puts
        ld hl, PANELS + 128
        call putshape
        ld hl, PANELS + 128
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 144
        ld b, 2
        ld c, 11
        call showblk            ; the panel, as 16 characters
        ld b, 7
        ld c, 11
        ld hl, t1
        call puts
        ld hl, PANELS + 256
        call putback
        ld hl, PANELS + 256
        call putor
        ld hl, PANELS + 256
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 160
        ld b, 2
        ld c, 20
        call showblk            ; the panel, as 16 characters
        ld b, 7
        ld c, 20
        ld hl, t2
        call puts
        ld hl, PANELS + 384
        call putback
        ld hl, PANELS + 384
        call putmask
        ld hl, PANELS + 384
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 176
        ld b, 11
        ld c, 2
        call showblk            ; the panel, as 16 characters
        ld b, 16
        ld c, 2
        ld hl, t3
        call puts
        ld hl, PANELS + 512
        call putback
        ld hl, PANELS + 512
        call putxor
        ld hl, PANELS + 512
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 192
        ld b, 11
        ld c, 11
        call showblk            ; the panel, as 16 characters
        ld b, 16
        ld c, 11
        ld hl, t4
        call puts
        ld hl, PANELS + 640
        call putback
        ld hl, PANELS + 640
        call putxor
        ld hl, PANELS + 640
        call putxor
        ld hl, PANELS + 640
        ld de, $0404            ; 4 bytes across, 4 rows of cells
        ld a, 208
        ld b, 11
        ld c, 20
        call showblk            ; the panel, as 16 characters
        ld b, 16
        ld c, 20
        ld hl, t5
        call puts
        ld ix, data
        ld b, 128               ; every byte of the panel
        ld c, 0                 ; C: the bytes where the two meet
hit:    ld a, (ix+0)
        and (ix+1)              ; background AND shape: 0 unless they share a 1
        jr z, miss
        inc c
miss:   inc ix
        inc ix
        inc ix
        djnz hit
        ld a, c
        ld (RESULTS), a
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; putback: one pass over the panel at HL, a byte at a time
putback:
        ld ix, data             ; three bytes for each byte of the panel
        ld b, 128
pb1:    ld a, (ix+0)            ; the background
        ld (hl), a
        inc hl                  ; the next byte of the panel
        inc ix
        inc ix
        inc ix                  ; the next three bytes of data
        djnz pb1
        ret

; putshape: one pass over the panel at HL, a byte at a time
putshape:
        ld ix, data             ; three bytes for each byte of the panel
        ld b, 128
ps1:    ld a, (ix+1)            ; the shape alone
        ld (hl), a
        inc hl                  ; the next byte of the panel
        inc ix
        inc ix
        inc ix                  ; the next three bytes of data
        djnz ps1
        ret

; putor: one pass over the panel at HL, a byte at a time
putor:
        ld ix, data             ; three bytes for each byte of the panel
        ld b, 128
po1:    ld a, (hl)
        or (ix+1)               ; the shape's 1s added
        ld (hl), a
        inc hl                  ; the next byte of the panel
        inc ix
        inc ix
        inc ix                  ; the next three bytes of data
        djnz po1
        ret

; putmask: one pass over the panel at HL, a byte at a time
putmask:
        ld ix, data             ; three bytes for each byte of the panel
        ld b, 128
pm1:    ld a, (hl)
        and (ix+2)              ; a hole where the shape goes ...
        or (ix+1)               ; ... and the shape in it
        ld (hl), a
        inc hl                  ; the next byte of the panel
        inc ix
        inc ix
        inc ix                  ; the next three bytes of data
        djnz pm1
        ret

; putxor: one pass over the panel at HL, a byte at a time
putxor:
        ld ix, data             ; three bytes for each byte of the panel
        ld b, 128
pxx1:   ld a, (hl)
        xor (ix+1)              ; every pixel under a 1 turned over
        ld (hl), a
        inc hl                  ; the next byte of the panel
        inc ix
        inc ix
        inc ix                  ; the next three bytes of data
        djnz pxx1
        ret

; showblk: a bitmap in the RAM or the ROM, W bytes across and 8 x H lines
;          down, line after line, sent to the VDP as W x H character shapes
;          from code A, and those characters put on the screen in a block
;          whose top left is row B, column C. HL = the bitmap, D = W, E = H.
;          The display must be off (chapter 20).
showblk:
        ld (blk_src), hl
        ld (blk_rc), bc
        ld (blk_k), a
        ld a, d
        ld (blk_w), a
        ld a, e
        ld (blk_h), a
        ld a, (blk_k)
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; the shape of character K is at K x 8
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, (blk_w)
        ld e, a
        ld d, 0                 ; DE: W, from one line to the next
        ld hl, (blk_src)
        ld a, (blk_h)
        ld b, a                 ; B: the rows of cells left
sb1:    push bc
        push hl                 ; HL: the top line of this row of cells
        ld a, (blk_w)
        ld c, a                 ; C: the cells left in the row
sb2:    push hl
        ld b, 8
sb3:    ld a, (hl)              ; the cell's eight lines, a byte each
        out (VDP_DATA), a
        add hl, de              ; one line down
        djnz sb3
        pop hl
        inc hl                  ; the next cell: one byte across
        dec c
        jr nz, sb2
        pop hl
        ld b, 8
sb4:    add hl, de
        djnz sb4                ; eight lines down: the next row of cells
        pop bc
        djnz sb1
        ld bc, (blk_rc)
        ld a, (blk_k)
        ld d, a                 ; D: the next code
        ld a, (blk_h)
        ld e, a                 ; E: the rows left
sn1:    call at                 ; the name of (B, C)
        ld a, (blk_w)
        ld h, a
sn2:    ld a, d
        out (VDP_DATA), a
        inc d
        dec h
        jr nz, sn2
        inc b
        dec e
        jr nz, sn1
        ret
t0:     db "BACK", 0
t1:     db "SHAPE", 0
t2:     db "OR", 0
t3:     db "MASK", 0
t4:     db "XOR", 0
t5:     db "XOR XOR", 0

data:
        db %11000000, %00000000, %11111111
        db %11000000, %00000000, %11111111
